import 'dart:typed_data';

/// Entity representing the multimodal result produced by Firebase AI and Dash photobooth.
class AiBadgeResult {
  /// The visually transformed image bytes (with Dash composition and Caribbean styling).
  final Uint8List imageBytes;

  /// The fun Caribbean title and vibe generated by Gemini Vision.
  final String aiVibeTitle;

  const AiBadgeResult({
    required this.imageBytes,
    required this.aiVibeTitle,
  });

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AiBadgeResult &&
          runtimeType == other.runtimeType &&
          aiVibeTitle == other.aiVibeTitle &&
          _bytesEqual(imageBytes, other.imageBytes);

  @override
  int get hashCode => aiVibeTitle.hashCode ^ imageBytes.length.hashCode;

  static bool _bytesEqual(Uint8List a, Uint8List b) {
    if (identical(a, b)) return true;
    if (a.length != b.length) return false;
    for (int i = 0; i < a.length; i++) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }
}
